function getAntiforgeryToken(){var n=document.querySelector('meta[name="request-verification-token"]');return n?n.getAttribute("content"):""}function getAntiforgeryFieldName(){var n=document.querySelector('meta[name="csrf-form-field-name"]');return n&&n.getAttribute("content")||"__RequestVerificationToken"}function getAntiforgeryHeaderName(){var n=document.querySelector('meta[name="csrf-header-name"]');return n&&n.getAttribute("content")||"RequestVerificationToken"}function appendAntiforgeryToken(n){var t=document.createElement("input");t.type="hidden";t.name=getAntiforgeryFieldName();t.value=getAntiforgeryToken();n.appendChild(t)}function ForeachObj(n,t){for(var i in n)n.hasOwnProperty(i)&&t(n,i)}function download(n,t){t="﻿"+t;var r=new Blob([t],{type:"text/plain;charset=UTF-8"}),u=window.URL.createObjectURL(r),i=document.createElement("a");i.setAttribute("href",u);i.setAttribute("download",n);i.style.display="none";document.body.appendChild(i);i.click();document.body.removeChild(i)}window.CloseConnection=function(){if(window.confirm("確定要關閉目前的連線嗎？")){var n=document.createElement("form");n.method="POST";n.action="/Home/CloseConnection";n.style.display="none";appendAntiforgeryToken(n);document.body.appendChild(n);n.submit();document.body.removeChild(n)}};